Method.Implementation:
  try 
  {
	set repNcid = ""
	set repNcid = ..GetHddNcidForRepFromHddNcidCache(rep,domain,context)
    if ( repNcid '= "")
    {
	    return
    }
	set servicePort = ##class(HddCommonService.HddCommonServicePort).%New()

    set servicePort.Location = ..Location


 	Set list = servicePort.getNcidsForRepresentation(rep, domain, context, ..dbEnv) 

 	if (list.Count() < 1)
 	{
	 	   $$$LOGERROR("HDD service did return value for Rep: " _ rep _ ", Domain: " _ domain _ ", Context:" _ context)
	 	   Set repNcid = "ERROR"
 	}
 	else
 	{
 	  For cnt=1:1:list.Count() 
 	  {
		  // Get the NCID in request context
		  Set ced = servicePort.getPreferredSurfaceForm(list.GetAt(cnt), context, ..dbEnv)
		  if $GET(ced)
		  {
		  	$$$TRACE("Service: Pref Name in " _ context _ " context for: " _list.GetAt(cnt) _ " = " _ ced.text)
		  	Set repNcid = list.GetAt(cnt)
		  	Do ..InsertValuesToHddNcidCache(repNcid, domain, context, rep)
		  	Quit
		  }

 	  }
      if (repNcid = "")
 	  {
	 	 Set repNcid = list.GetAt(1)
	  }  
 	}
  }

    CATCH exceptionvar
    {
	  Set repNcid = "ERROR"  
	  If $ZERROR["<ZSOAP>" {
	     set errTxt = $System.Status.GetErrorText(%objlasterror)
         $$$LOGERROR("Exception in GetHddNcidForRep:  Rep: " _ rep _ ", Domain: " _ domain _ ", Context:" _ context _ " = " _ errTxt _ ", Excp:" _ exceptionvar.Name _ " " _ exceptionvar.Code _ " " _ exceptionvar.Location )
         $$$LOGERROR($ZERROR)
	  }
	  else
	  {
		  throw exceptionvar
	  }

    }

  try 
  {
 	Set rep = ""
 	set rep = ..GetHddRepForNcidFromHddRepCache(ncid, context)
	if (rep '= "")
	{
	  	return
	}
	set servicePort = ##class(HddCommonService.HddCommonServicePort).%New()
  	set servicePort.Location = ..Location
		  Set ced = servicePort.getPreferredSurfaceForm(ncid, context, ..dbEnv)
		  if $GET(ced)
		  {
		  	Set rep = ced.text
		  	$$$TRACE("getPreferredSurfaceForm " _ ncid _ ": " _rep)
		  	Do ..InsertValuesToHddRepCache(ncid, context, rep)
		  	Quit
		  }
		  else
		  {
			  Set rep = "ERROR" 
		  }

	}  
    CATCH exceptionvar
    {
     Set rep = "ERROR"  
	  If $ZERROR["<ZSOAP>" {
	     set errTxt = $System.Status.GetErrorText(%objlasterror)
	     Set repNcid = errTxt
         $$$LOGERROR("Exception in GetHddRepForNcid NCID: " _ncid _", Context: " _ context _ " = " _ errTxt _ ", Excp:" _ exceptionvar.Name _ " " _ exceptionvar.Code _ " " _ exceptionvar.Location)
         $$$LOGERROR($ZERROR)
	  }
	  else
	  {
		  throw exceptionvar
	  }
    }

	 //Get current time
 SET todayInt=$PIECE($HOROLOG,",",1)
 SET nowInt=$PIECE($HOROLOG,",",2)
 $$$TRACE( "Now: (" _ todayInt _ ", " _ nowInt _")")

 if ($DATA(^NextRef) = 0)
 {
	 $$$TRACE(  "Set global: ^NextRef")
	 set ^NextRef(1)= todayInt _ "," _ (nowInt - 50)
 }

 // Get Next refresh time
 SET nextdateref=$PIECE($GET(^NextRef(1)),",",1)
 SET nexttimeref=$PIECE($GET(^NextRef(1)),",",2)

 $$$TRACE(  "NEXT REFRESH: (" _ nextdateref _ ", " _ nexttimeref _")")


 if ((todayInt < nextdateref) || ((todayInt = nextdateref) && (nowInt < nexttimeref)) )
 {
	 $$$TRACE( "REFRESH Due on: " _ $ZDATETIME(^NextRef(1)) _ " = " _(nextdateref - todayInt) _ " : " _ (nexttimeref - nowInt))
 }
 else
 {
	 $$$TRACE(  "REFRESH NOW "  _ (nextdateref - todayInt) _ " : " _ (nexttimeref - nowInt))
	 &sql(DELETE IHC_ITF_ITFCOMMON_DataStructure.HddRepCache)
	 &sql(DELETE IHC_ITF_ITFCOMMON_DataStructure.HddNcidCache)
	  // Get refresh date and time
	  set hddUpdateDay = ..HddUpdateDay ; Sunday: 0, Monday: 1, Saturday: 6
	  if ( (hddUpdateDay < 0) || (hddUpdateDay > 7))
	  {
		  $$$LOGERROR("HddUpdateDay not set, value should be between 0 and 7")
		  return
	  }

      // Calculate next refresh date
	  set dayOfWeek = $ZDATE($HOROLOG,10)
	  set daysLeft = $SELECT( (dayOfWeek > hddUpdateDay) : (7 - dayOfWeek + hddUpdateDay),(dayOfWeek = hddUpdateDay) : 7, 1 : (hddUpdateDay - dayOfWeek) )
	  set refdatezh = todayInt + daysLeft

	  // Next refresh time
      SET hddUpdateTime= ..HddUpdateTime  ; format: "hh:mm" (24-hour clock).
      if ( ($MATCH(hddUpdateTime, "\d\d:\d\d") = 1) || ($MATCH(hddUpdateTime, "\d:\d\d") = 1) )
 	  {

 	  	set hddUpdateTimezh = $ZTIMEH(hddUpdateTime,2)
 	  	if (hddUpdateTimezh <= 0)
 	  	{
	 	  	$$$LOGERROR("HddUpdateTime not set")
	 		  return
 	  	}
 	  }
 	  else
 	  {
 	  	$$$LOGERROR("HddUpdateTime not set correctly: HH:MM")
	 	  return
 	  }

      set ^NextRef(1)= refdatezh _ "," _ hddUpdateTimezh
      $$$TRACE(  "NEXT REFRESH: " _ $ZDATETIME(^NextRef(1)))
 }
